<?php $visibility = function_exists( 'sd_core_profile_visibility' ) ? sd_core_profile_visibility( get_current_user_id() ) : 'public'; ?><div class="sd-onboarding-step"><span class="sd-eyebrow"><?php esc_html_e( 'Step 5 of 6', 'social-discovery' ); ?></span><h2><?php esc_html_e( 'Choose your profile visibility', 'social-discovery' ); ?></h2><p><?php esc_html_e( 'This controls who can view the profile fields managed by Social Discovery.', 'social-discovery' ); ?></p><div class="sd-privacy-options"><?php foreach ( array( 'public' => __( 'Public', 'social-discovery' ), 'members' => __( 'Members only', 'social-discovery' ), 'private' => __( 'Private', 'social-discovery' ) ) as $key => $label ) : ?><label><input type="radio" name="profile_visibility" value="<?php echo esc_attr( $key ); ?>" <?php checked( $visibility, $key ); ?>><span><strong><?php echo esc_html( $label ); ?></strong><small><?php echo esc_html( 'public' === $key ? __( 'Anyone can view public profile information.', 'social-discovery' ) : ( 'members' === $key ? __( 'Only signed-in members can view it.', 'social-discovery' ) : __( 'Only you and site administrators can view it.', 'social-discovery' ) ) ); ?></small></span></label><?php endforeach; ?></div></div>
